CREATE TRIGGER customer_access_owner_insert BEFORE INSERT ON customer_order_access WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND seller_id=NEW.seller_id) BEGIN SELECT RAISE(ABORT,'Customer grant ownership violation'); END;
CREATE TRIGGER customer_access_owner_update BEFORE UPDATE OF seller_id,order_id ON customer_order_access WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND seller_id=NEW.seller_id) BEGIN SELECT RAISE(ABORT,'Customer grant ownership violation'); END;
CREATE TRIGGER reservation_owner_insert BEFORE INSERT ON subscription_reservations WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND seller_id=NEW.seller_id) BEGIN SELECT RAISE(ABORT,'Reservation ownership violation'); END;
CREATE TRIGGER reservation_owner_update BEFORE UPDATE OF seller_id,order_id ON subscription_reservations WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND seller_id=NEW.seller_id) BEGIN SELECT RAISE(ABORT,'Reservation ownership violation'); END;
CREATE TRIGGER compensation_owner_insert BEFORE INSERT ON compensation_requests WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND seller_id=NEW.seller_id) BEGIN SELECT RAISE(ABORT,'Compensation ownership violation'); END;
CREATE TRIGGER compensation_owner_update BEFORE UPDATE OF seller_id,order_id ON compensation_requests WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND seller_id=NEW.seller_id) BEGIN SELECT RAISE(ABORT,'Compensation ownership violation'); END;
CREATE TRIGGER financial_owner_insert BEFORE INSERT ON financial_events WHEN NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.seller_id) OR (NEW.fulfillment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fulfillments f JOIN order_items oi ON oi.id=f.order_item_id JOIN orders o ON o.id=oi.order_id WHERE f.id=NEW.fulfillment_id AND o.seller_id=NEW.seller_id)) BEGIN SELECT RAISE(ABORT,'Financial event ownership violation'); END;
CREATE TRIGGER submission_payload_insert BEFORE INSERT ON provider_submission_attempts WHEN NOT json_valid(NEW.request_json) BEGIN SELECT RAISE(ABORT,'Invalid submission payload'); END;
